     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→  // true일 때 parsePostfix에서 { 를 구조체 리터럴로 해석하지 않음
    13→  private noStructLiteral: boolean = false;
    14→
    15→  constructor(tokens: Token[]) {
    16→    this.tokens = tokens;
    17→  }
    18→
    19→  /**
    20→   * 파싱 진입점
    21→   */
    22→  parse(): AST.Program {
    23→    const body: Array<AST.VFunction | AST.PyFunction | AST.StructDef | AST.Statement | AST.ExternCall | AST.LangBlock | AST.SharedMemDirective> = [];
    24→
    25→    while (!this.isAtEnd()) {
    26→      this.skipNewlines();
    27→      if (this.isAtEnd()) break;
    28→
    29→      const token = this.peek();
    30→
    31→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    32→      if (token.type === TokenType.MODE_MARKER) {
    33→        this.advance();
    34→        continue;
    35→      }
    36→
    37→      // @shared_mem 디렉티브 (공유 메모리)
    38→      if (token.type === TokenType.LANG_SHARED_MEM) {
    39→        const sharedMem = this.parseSharedMemDirective();
    40→        if (sharedMem) body.push(sharedMem);
    41→        continue;
    42→      }
    43→
    44→      // @lang 디렉티브 (다중언어 블록)
    45→      if (token.type === TokenType.LANG_DIRECTIVE) {
    46→        const langBlock = this.parseLangBlock();
    47→        if (langBlock) body.push(langBlock);
    48→        continue;
    49→      }
    50→
    51→      // @call 디렉티브
    52→      if (token.type === TokenType.CALL_DIRECTIVE) {
    53→        const callNode = this.parseCallDirective();
    54→        if (callNode) body.push(callNode);
    55→        continue;
    56→      }
    57→
    58→      // 탑레벨 아이템 파싱
    59→      const item = this.parseTopLevel();
    60→      if (item) {
    61→        body.push(item);
    62→      }
    63→    }
    64→
    65→    return { type: 'Program', body };
    66→  }
    67→
    68→  /**
    69→   * @call 디렉티브 파싱
    70→   * 토큰 value: "@call python:numpy 1.24" 또는 "@call rust:rand as r"
    71→   *
    72→   * 문법: @call <lang>:<package> [<version>] [as <alias>]
    73→   */
    74→  private parseCallDirective(): AST.ExternCall | null {
    75→    const token = this.advance(); // CALL_DIRECTIVE 토큰 소비
    76→    const raw = token.value; // "@call python:numpy 1.24"
    77→
    78→    // "@call " 제거
    79→    const body = raw.slice('@call '.length).trim();
    80→
    81→    // lang:package 분리
    82→    const colonIdx = body.indexOf(':');
    83→    if (colonIdx === -1) return null;
    84→
    85→    const lang = body.slice(0, colonIdx).trim() as AST.ExternCall['lang'];
    86→    const rest = body.slice(colonIdx + 1).trim();
    87→
    88→    // "as alias" 분리
    89→    let alias: string | undefined;
    90→    let packageAndVersion = rest;
    91→    const asIdx = rest.search(/\s+as\s+/);
    92→    if (asIdx !== -1) {
    93→      alias = rest.slice(asIdx).replace(/\s+as\s+/, '').trim();
    94→      packageAndVersion = rest.slice(0, asIdx).trim();
    95→    }
    96→
    97→    // package와 version 분리 (마지막 공백 기준)
    98→    const parts = packageAndVersion.split(/\s+/);
    99→    const pkg = parts[0];
   100→    const version = parts.length > 1 ? parts[parts.length - 1] : undefined;

