     1→/**
     2→ * FreeLang Nexus - 통합 Lexer
     3→ * V 모드 + Python 모드를 동시에 지원
     4→ *
     5→ * PyFree의 INDENT/DEDENT 패턴 + FV의 복합 연산자 처리 + 모드 전환
     6→ */
     7→
     8→import {
     9→  Token,
    10→  TokenType,
    11→  getKeywordToken,
    12→  detectMode,
    13→  V_KEYWORDS,
    14→  PYTHON_KEYWORDS,
    15→} from './token';
    16→import { ModeDetector } from './mode-detector';
    17→
    18→export class NexusLexer {
    19→  private source: string;
    20→  private pos: number = 0;
    21→  private line: number = 1;
    22→  private column: number = 1;
    23→  private currentMode: 'v' | 'python' | 'auto' = 'auto';
    24→  private indentStack: number[] = [0]; // Python INDENT/DEDENT 스택 (PyFree 패턴)
    25→  private atLineStart: boolean = true; // Python 들여쓰기 처리용
    26→  private tokens: Token[] = [];
    27→
    28→  constructor(source: string) {
    29→    this.source = source;
    30→  }
    31→
    32→  /**
    33→   * 전체 소스 토큰화
    34→   */
    35→  tokenize(): Token[] {
    36→    while (this.pos < this.source.length) {
    37→      const token = this.nextToken();
    38→      if (token) {
    39→        this.tokens.push(token);
    40→      }
    41→    }
    42→
    43→    // EOF 토큰 추가
    44→    this.tokens.push(this.makeToken(TokenType.EOF, '', this.currentMode));
    45→
    46→    return this.tokens;
    47→  }
    48→
    49→  /**
    50→   * 다음 토큰 가져오기
    51→   */
    52→  private nextToken(): Token | null {
    53→    const ch = this.peek();
    54→
    55→    if (ch === undefined) {
    56→      return null;
    57→    }
    58→
    59→    // 개행
    60→    if (ch === '\n') {
    61→      this.advance();
    62→      this.atLineStart = true;
    63→      this.column = 1;
    64→      return this.makeToken(TokenType.NEWLINE, '\n', this.currentMode);
    65→    }
    66→
    67→    // 줄 시작에서 들여쓰기 처리 (Python 모드)
    68→    if (this.atLineStart && this.currentMode === 'python') {
    69→      const indentToken = this.handleIndentation();
    70→      this.atLineStart = false;
    71→      if (indentToken) {
    72→        return indentToken;
    73→      }
    74→    }
    75→
    76→    // 공백 (탭, 스페이스) - 이미 라인 시작 처리됨
    77→    if (this.isWhitespace(ch)) {
    78→      this.skipWhitespace();
    79→      return this.nextToken(); // 재귀 호출
    80→    }
    81→
    82→    // 주석: V 모드는 //, Python 모드는 #
    83→    if (ch === '/' && this.peek(1) === '/' && this.currentMode === 'v') {
    84→      this.skipLineComment();
    85→      return this.nextToken(); // 재귀 호출
    86→    }
    87→
    88→    if (ch === '#' && this.currentMode === 'python') {
    89→      this.skipLineComment();
    90→      return this.nextToken(); // 재귀 호출
    91→    }
    92→
    93→    // --- raw 블록 (다중언어 코드) - 줄 시작에만 적용
    94→    if (ch === '-' && this.peek(1) === '-' && this.peek(2) === '-' && this.atLineStart) {
    95→      return this.tokenizeRawBlock();
    96→    }
    97→
    98→    // @ 디렉티브 (@mode, @call, @lang, @artifact, @compile)
    99→    if (ch === '@') {
   100→      const modeToken = this.tryParseMode();
   101→      if (modeToken) return modeToken;
   102→
   103→      const langToken = this.tryParseLangDirective();
   104→      if (langToken) return langToken;
   105→
   106→      const callToken = this.tryParseCall();
   107→      if (callToken) return callToken;
   108→    }
   109→
   110→    // 문자열
   111→    if (ch === '"' || ch === "'" || (ch === 'f' && (this.peek(1) === '"' || this.peek(1) === "'"))) {
   112→      return this.tokenizeString();
   113→    }
   114→
   115→    // 숫자
   116→    if (this.isDigit(ch)) {
   117→      return this.tokenizeNumber();
   118→    }
   119→
   120→    // 식별자 또는 키워드
   121→    if (this.isIdentifierStart(ch)) {
   122→      return this.tokenizeIdentifierOrKeyword();
   123→    }
   124→
   125→    // 연산자
   126→    const operatorToken = this.tokenizeOperator();
   127→    if (operatorToken) {
   128→      return operatorToken;
   129→    }
   130→
   131→    // 알 수 없는 문자
   132→    throw new Error(`Unknown character: '${ch}' at line ${this.line}, column ${this.column}`);
   133→  }
   134→
   135→  /**
   136→   * 들여쓰기 처리 (Python 모드 전용)
   137→   * PyFree 패턴 재사용
   138→   */
   139→  private handleIndentation(): Token | null {
   140→    let indent = 0;
   141→
   142→    // 현재 위치에서 연속된 스페이스/탭 세기 (이미 라인 시작에 있다고 가정)
   143→    const lineStart = this.pos;
   144→    while (this.pos < this.source.length) {
   145→      const ch = this.peek();
   146→      if (ch === ' ') {
   147→        indent += 1;
   148→        this.pos++;
   149→      } else if (ch === '\t') {
   150→        indent += 8; // 탭 = 8 스페이스
   151→        this.pos++;
   152→      } else {
   153→        break;
   154→      }
   155→    }
   156→
   157→    // 라인이 비어있으면 (주석/개행만) 들여쓰기 무시
   158→    const ch = this.peek();
   159→    if (ch === '\n' || ch === '#' || ch === undefined) {
   160→      this.pos = lineStart;
   161→      return null;
   162→    }
   163→
   164→    const currentIndent = this.indentStack[this.indentStack.length - 1] || 0;
   165→
   166→    if (indent > currentIndent) {
   167→      // INDENT
   168→      this.indentStack.push(indent);
   169→      return this.makeToken(TokenType.INDENT, '\t', this.currentMode);
   170→    } else if (indent < currentIndent) {
   171→      // DEDENT
   172→      while (this.indentStack.length > 0 && this.indentStack[this.indentStack.length - 1] > indent) {
   173→        this.indentStack.pop();
   174→      }
   175→      return this.makeToken(TokenType.DEDENT, '', this.currentMode);
   176→    }
   177→
   178→    return null;
   179→  }
   180→
   181→  /**
   182→   * 식별자 또는 키워드 토큰화
   183→   */
   184→  private tokenizeIdentifierOrKeyword(): Token {
   185→    const start = this.pos;
   186→    const startColumn = this.column;
   187→
   188→    while (this.pos < this.source.length && this.isIdentifierChar(this.peek())) {
   189→      this.advance();
   190→    }
   191→
   192→    const value = this.source.substring(start, this.pos);
   193→
   194→    // 키워드 확인
   195→    const keywordType = getKeywordToken(value, this.currentMode);
   196→    if (keywordType) {
   197→      return this.makeToken(keywordType, value, this.currentMode);
   198→    }
   199→
   200→    return this.makeToken(TokenType.IDENTIFIER, value, this.currentMode);
   201→  }
   202→
   203→  /**
   204→   * 숫자 토큰화
   205→   */
   206→  private tokenizeNumber(): Token {
   207→    const start = this.pos;
   208→
   209→    // 16진수 (0x)
   210→    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
   211→      this.advance(); // '0'
   212→      this.advance(); // 'x'
   213→      while (this.isHexDigit(this.peek())) {
   214→        this.advance();
   215→      }
   216→    }
   217→    // 2진수 (0b)
   218→    else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
   219→      this.advance(); // '0'
   220→      this.advance(); // 'b'
   221→      while (this.peek() === '0' || this.peek() === '1') {
   222→        this.advance();
   223→      }
   224→    }
   225→    // 8진수 (0o)
   226→    else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
   227→      this.advance(); // '0'
   228→      this.advance(); // 'o'
   229→      while (this.isOctalDigit(this.peek())) {
   230→        this.advance();
   231→      }
   232→    }
   233→    // 10진수 (정수 또는 실수)
   234→    else {
   235→      while (this.isDigit(this.peek())) {
   236→        this.advance();
   237→      }
   238→
   239→      // 실수: . 또는 e/E
   240→      if (this.peek() === '.' && this.isDigit(this.peek(1))) {
   241→        this.advance(); // '.'
   242→        while (this.isDigit(this.peek())) {
   243→          this.advance();
   244→        }
   245→      }
   246→
   247→      if (this.peek() === 'e' || this.peek() === 'E') {
   248→        this.advance();
   249→        if (this.peek() === '+' || this.peek() === '-') {
   250→          this.advance();
   251→        }
   252→        while (this.isDigit(this.peek())) {
   253→          this.advance();
   254→        }
   255→      }
   256→    }
   257→
   258→    const value = this.source.substring(start, this.pos);
   259→    return this.makeToken(TokenType.NUMBER, value, this.currentMode);
   260→  }
   261→
   262→  /**
   263→   * 문자열 토큰화
   264→   */
   265→  private tokenizeString(): Token {
   266→    const start = this.pos;
   267→    let isFString = false;
   268→
   269→    // f-string 확인
   270→    if (this.peek() === 'f' && (this.peek(1) === '"' || this.peek(1) === "'")) {
   271→      isFString = true;
   272→      this.advance(); // 'f'
   273→    }
   274→
   275→    const quote = this.peek();
   276→    this.advance(); // 첫 따옴표
   277→
   278→    // 3중 따옴표 확인
   279→    let isTriple = false;
   280→    if (this.peek() === quote && this.peek(1) === quote) {
   281→      isTriple = true;
   282→      this.advance();
   283→      this.advance();
   284→    }
   285→
   286→    // 문자열 내용 읽기
   287→    while (this.pos < this.source.length) {
   288→      const ch = this.peek();
   289→
   290→      if (isTriple) {
   291→        if (ch === quote && this.peek(1) === quote && this.peek(2) === quote) {
   292→          this.advance();
   293→          this.advance();
   294→          this.advance();
   295→          break;
   296→        }
   297→      } else {
   298→        if (ch === quote) {
   299→          this.advance();
   300→          break;
   301→        }
   302→        if (ch === '\n') {
   303→          throw new Error(`Unterminated string at line ${this.line}`);
   304→        }
   305→      }
   306→
   307→      if (ch === '\\') {
   308→        this.advance(); // 이스케이프 문자 다음
   309→        if (this.pos < this.source.length) {
   310→          this.advance();
   311→        }
   312→      } else {
   313→        this.advance();
   314→      }
   315→    }
   316→
   317→    const value = this.source.substring(start, this.pos);
   318→    return this.makeToken(TokenType.STRING, value, this.currentMode);
   319→  }
   320→
   321→  /**
   322→   * 연산자 토큰화
   323→   */
   324→  /**
   325→   * --- 다중언어 블록 파싱 (raw 코드)
   326→   * ---
   327→   * <raw code - 어떤 문자든 가능>
   328→   * ---
   329→   */
   330→  private tokenizeRawBlock(): Token {
   331→    const startLine = this.line;
   332→    const startColumn = this.column;
   333→
   334→    // 시작 --- 스킵
   335→    this.advance(); // -
   336→    this.advance(); // -
   337→    this.advance(); // -
   338→
   339→    // 줄 끝까지 스킵 (주석 가능)
   340→    while (this.pos < this.source.length && this.peek() !== '\n') {
   341→      this.advance();
   342→    }
   343→    if (this.peek() === '\n') {
   344→      this.advance(); // 줄 끝 개행
   345→      this.atLineStart = true;
   346→    }
   347→
   348→    // 다음 --- 까지의 모든 내용 수집 (반드시 줄 시작에 있어야 함)
   349→    let content = '';
   350→    while (this.pos < this.source.length) {
   351→      const ch = this.peek();
   352→      const next1 = this.peek(1);
   353→      const next2 = this.peek(2);
   354→
   355→      // 줄 시작에서 ---를 찾음
   356→      if (this.atLineStart && ch === '-' && next1 === '-' && next2 === '-') {
   357→        // 종료 --- 찾음
   358→        break;
   359→      }
   360→
   361→      content += ch;
   362→      if (ch === '\n') {
   363→        this.line++;
   364→        this.column = 1;
   365→        this.atLineStart = true;
   366→      } else {
   367→        this.column++;
   368→        if (!this.isWhitespace(ch)) {
   369→          this.atLineStart = false;
   370→        }
   371→      }
   372→      this.pos++;
   373→    }
   374→
   375→    // 종료 --- 스킵
   376→    if (this.peek() === '-' && this.peek(1) === '-' && this.peek(2) === '-') {
   377→      this.advance(); // -
   378→      this.advance(); // -
   379→      this.advance(); // -
   380→      // 줄 끝까지 스킵
   381→      while (this.pos < this.source.length && this.peek() !== '\n') {
   382→        this.advance();
   383→      }
   384→      if (this.peek() === '\n') {
   385→        this.advance();
   386→      }
   387→      this.atLineStart = true;
   388→    }
   389→
   390→    return this.makeToken(TokenType.STRING, content, this.currentMode);
   391→  }
   392→
   393→  private tokenizeOperator(): Token | null {
   394→    const ch = this.peek();
   395→    const next = this.peek(1);
   396→    const next2 = this.peek(2);
   397→
   398→    if (ch === '.' && next === '.' && next2 === '=') {
   399→      this.advance();
   400→      this.advance();
   401→      this.advance();
   402→      return this.makeToken(TokenType.IDENTIFIER, '..=', this.currentMode); // 커스텀
   403→    }
   404→
   405→    // 2글자 연산자
   406→    const twoChar = ch && next ? ch + next : '';
   407→    const twoCharMap: Record<string, TokenType> = {
   408→      '->': TokenType.ARROW,
   409→      '=>': TokenType.IDENTIFIER, // FatArrow (커스텀)
   410→      '==': TokenType.EQ,
   411→      '!=': TokenType.NE,
   412→      '<=': TokenType.LE,
   413→      '>=': TokenType.GE,
   414→      '&&': TokenType.AND,
   415→      '||': TokenType.OR,
   416→      '::': TokenType.IDENTIFIER, // DoubleColon (커스텀)
   417→      '..': TokenType.IDENTIFIER, // DotDot (커스텀)
   418→      '//': TokenType.SLASH, // 이미 주석 처리됨
   419→      '**': TokenType.STAR, // Power (커스텀)
   420→    };
   421→
   422→    if (twoCharMap[twoChar]) {
   423→      this.advance();
   424→      this.advance();
   425→      return this.makeToken(twoCharMap[twoChar], twoChar, this.currentMode);
   426→    }
   427→
   428→    // 1글자 연산자
   429→    const oneCharMap: Record<string, TokenType> = {
   430→      '(': TokenType.LPAREN,
   431→      ')': TokenType.RPAREN,
   432→      '{': TokenType.LBRACE,
   433→      '}': TokenType.RBRACE,
   434→      '[': TokenType.LBRACKET,
   435→      ']': TokenType.RBRACKET,
   436→      ',': TokenType.COMMA,
   437→      '.': TokenType.DOT,
   438→      ';': TokenType.SEMICOLON,
   439→      ':': TokenType.COLON,
   440→      '=': TokenType.EQUAL,
   441→      '+': TokenType.PLUS,
   442→      '-': TokenType.MINUS,
   443→      '*': TokenType.STAR,
   444→      '/': TokenType.SLASH,
   445→      '%': TokenType.PERCENT,
   446→      '<': TokenType.LT,
   447→      '>': TokenType.GT,
   448→      '!': TokenType.NOT,
   449→      '&': TokenType.AMPERSAND,
   450→      '|': TokenType.PIPE,
   451→      '@': TokenType.AT,
   452→    };
   453→
   454→    if (ch && oneCharMap[ch]) {
   455→      this.advance();
   456→      return this.makeToken(oneCharMap[ch], ch, this.currentMode);
   457→    }
   458→
   459→    return null;
   460→  }
   461→
   462→  /**
   463→   * @mode() 디렉티브 파싱
   464→   */
   465→  private tryParseMode(): Token | null {
   466→    const start = this.pos;
   467→
   468→    if (this.peek() !== '@') {
   469→      return null;
   470→    }
   471→
   472→    this.advance(); // '@'
   473→
   474→    // @mode 확인
   475→    if (
   476→      this.peek() === 'm' &&
   477→      this.peek(1) === 'o' &&
   478→      this.peek(2) === 'd' &&
   479→      this.peek(3) === 'e'
   480→    ) {
   481→      this.advance();
   482→      this.advance();
   483→      this.advance();
   484→      this.advance();
   485→
   486→      // 공백 및 ( 확인
   487→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   488→        this.advance();
   489→      }
   490→
   491→      if (this.peek() !== '(') {
   492→        // @mode가 아니면 다시 돌아가기
   493→        this.pos = start;
   494→        return null;
   495→      }
   496→
   497→      this.advance(); // '('
   498→
   499→      // 공백
   500→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   501→        this.advance();
   502→      }
   503→
   504→      // v 또는 python 확인
   505→      let mode: 'v' | 'python' | null = null;
   506→
   507→      if (this.peek() === 'v' && (this.peek(1) === ')' || this.isWhitespace(this.peek(1)))) {
   508→        mode = 'v';
   509→        this.advance();
   510→      } else if (
   511→        this.peek() === 'p' &&
   512→        this.peek(1) === 'y' &&
   513→        this.peek(2) === 't' &&
   514→        this.peek(3) === 'h' &&
   515→        this.peek(4) === 'o' &&
   516→        this.peek(5) === 'n'
   517→      ) {
   518→        mode = 'python';
   519→        this.advance();
   520→        this.advance();
   521→        this.advance();
   522→        this.advance();
   523→        this.advance();
   524→        this.advance();
   525→      }
   526→
   527→      if (!mode) {
   528→        // 유효한 모드가 아니면 다시 돌아가기
   529→        this.pos = start;
   530→        return null;
   531→      }
   532→
   533→      // 공백 및 ) 확인
   534→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   535→        this.advance();
   536→      }
   537→
   538→      if (this.peek() !== ')') {
   539→        this.pos = start;
   540→        return null;
   541→      }
   542→
   543→      this.advance(); // ')'
   544→
   545→      // 모드 전환!
   546→      this.currentMode = mode;
   547→
   548→      const value = this.source.substring(start, this.pos);
   549→      return this.makeToken(TokenType.MODE_MARKER, value, mode);
   550→    }
   551→
   552→    this.pos = start;
   553→    return null;
   554→  }
   555→
   556→  /**
   557→   * @lang(), @artifact(), @compile(), @cgo, @shared_mem, @depends_on 디렉티브 파싱
   558→   * @lang("rust")
   559→   * @artifact("librustcore.so")
   560→   * @compile("rustc --crate-type cdylib ...")
   561→   * @cgo
   562→   * @shared_mem("name", size=N, type="i64")
   563→   * @depends_on("artifact_name")
   564→   */
   565→  private tryParseLangDirective(): Token | null {
   566→    const start = this.pos;
   567→
   568→    if (this.peek() !== '@') return null;
   569→    this.advance(); // '@'
   570→
   571→    // 디렉티브 키워드 확인
   572→    let directive: 'lang' | 'artifact' | 'compile' | 'cgo' | 'shared_mem' | 'depends_on' | null = null;
   573→    for (const kw of ['lang', 'artifact', 'compile', 'cgo', 'shared_mem', 'depends_on']) {
   574→      if (this.source.substr(this.pos, kw.length) === kw &&
   575→          !this.isIdentifierChar(this.source[this.pos + kw.length])) {
   576→        directive = kw as 'lang' | 'artifact' | 'compile' | 'cgo' | 'shared_mem' | 'depends_on';
   577→        for (let i = 0; i < kw.length; i++) {
   578→          this.advance();
   579→        }
   580→        break;
   581→      }
   582→    }
   583→
   584→    if (!directive) {
   585→      this.pos = start;
   586→      return null;
   587→    }
   588→
   589→    // @cgo는 파라미터 없음 (뒤에 newline이나 다른 토큰 와야 함)
   590→    if (directive === 'cgo') {
   591→      return this.makeToken(TokenType.LANG_CGO, '@cgo', this.currentMode);
   592→    }
   593→
   594→    // '(' 확인
   595→    while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   596→      this.advance();
   597→    }
   598→
   599→    if (this.peek() !== '(') {
   600→      this.pos = start;
   601→      return null;
   602→    }
   603→    this.advance(); // '('
   604→
   605→    // 문자열/값 파싱 (따옴표 안 또는 파라미터)
   606→    const stringStart = this.pos;
   607→    let stringValue = '';
   608→    const quoteChar = this.peek();
   609→
   610→    if (quoteChar !== '"' && quoteChar !== "'") {
   611→      // @shared_mem이나 @depends_on은 파라미터가 있을 수 있음 (이 경우 따옴표 없을 수도)
   612→      // 현재는 따옴표 필수로 처리
   613→      this.pos = start;
   614→      return null;
   615→    }
   616→    this.advance(); // 시작 따옴표
   617→
   618→    // 따옴표 종료까지 읽기
   619→    while (this.pos < this.source.length && this.peek() !== quoteChar) {
   620→      if (this.peek() === '\\') {
   621→        stringValue += this.peek();
   622→        this.advance();
   623→        stringValue += this.peek();
   624→        this.advance();
   625→      } else {
   626→        stringValue += this.peek();
   627→        this.advance();
   628→      }
   629→    }
   630→
   631→    if (this.peek() !== quoteChar) {
   632→      this.pos = start;
   633→      return null;
   634→    }
   635→    this.advance(); // 종료 따옴표
   636→
   637→    // ')' 확인
   638→    if (this.peek() !== ')') {
   639→      this.pos = start;
   640→      return null;
   641→    }
   642→    this.advance(); // ')'
   643→
   644→    // 토큰 생성
   645→    let tokenType: TokenType;
   646→    if (directive === 'lang') {
   647→      tokenType = TokenType.LANG_DIRECTIVE;
   648→    } else if (directive === 'artifact') {
   649→      tokenType = TokenType.LANG_ARTIFACT;
   650→    } else if (directive === 'compile') {
   651→      tokenType = TokenType.LANG_COMPILE_CMD;
   652→    } else if (directive === 'shared_mem') {
   653→      tokenType = TokenType.LANG_SHARED_MEM;
   654→    } else if (directive === 'depends_on') {
   655→      tokenType = TokenType.LANG_DEPENDS_ON;
   656→    } else {
   657→      tokenType = TokenType.LANG_CGO;
   658→    }
   659→
   660→    const value = `@${directive}("${stringValue}")`;
   661→    return this.makeToken(tokenType, value, this.currentMode);
   662→  }
   663→
   664→  /**
   665→   * @call 디렉티브 파싱
   666→   * @call python:numpy
   667→   * @call python:numpy 1.24
   668→   * @call rust:rand 0.8
   669→   * @call go:github.com/gin-gonic/gin
   670→   * @call python:numpy as np
   671→   *
   672→   * 토큰 value = "@call python:numpy 1.24" (전체 raw 문자열)
   673→   */
   674→  private tryParseCall(): Token | null {
   675→    const start = this.pos;
   676→
   677→    if (this.peek() !== '@') return null;
   678→    this.advance(); // '@'
   679→
   680→    // "call" 확인
   681→    const keyword = 'call';
   682→    for (let i = 0; i < keyword.length; i++) {
   683→      if (this.peek() !== keyword[i]) {
   684→        this.pos = start;
   685→        return null;
   686→      }
   687→      this.advance();
   688→    }
   689→
   690→    // 공백 확인 (필수)
   691→    if (!this.isWhitespace(this.peek()) || this.peek() === '\n') {
   692→      this.pos = start;
   693→      return null;
   694→    }
   695→    while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   696→      this.advance();
   697→    }
   698→
   699→    // 나머지 줄 끝까지 읽기 (lang:package [version] [as alias])
   700→    const restStart = this.pos;
   701→    while (this.pos < this.source.length && this.peek() !== '\n') {
   702→      this.advance();
   703→    }
   704→    const rest = this.source.substring(restStart, this.pos).trim();
   705→
   706→    const value = `@call ${rest}`;
   707→    return this.makeToken(TokenType.CALL_DIRECTIVE, value, this.currentMode);
   708→  }
   709→
   710→  // ==================== 헬퍼 함수 ====================
   711→
   712→  private skipWhitespaceOnLineStart(): void {
   713→    // 라인 시작의 공백 스킵
   714→    while (this.pos < this.source.length) {
   715→      const ch = this.peek();
   716→      if (ch === ' ' || ch === '\t') {
   717→        this.advance();
   718→      } else if (ch === '\n') {
   719→        this.advance();
   720→        this.atLineStart = true;
   721→      } else {
   722→        break;
   723→      }
   724→    }
   725→  }
   726→
   727→  private skipWhitespace(): void {
   728→    while (this.pos < this.source.length && this.isWhitespace(this.peek())) {
   729→      this.advance();
   730→    }
   731→  }
   732→
   733→  private skipLineComment(): void {
   734→    while (this.pos < this.source.length && this.peek() !== '\n') {
   735→      this.advance();
   736→    }
   737→  }
   738→
   739→  private peek(offset: number = 0): string | undefined {
   740→    return this.source[this.pos + offset];
   741→  }
   742→
   743→  private advance(): void {
   744→    const ch = this.peek();
   745→    if (ch === '\n') {
   746→      this.line++;
   747→      this.column = 1;
   748→    } else {
   749→      this.column++;
   750→    }
   751→    this.pos++;
   752→  }
   753→
   754→  private isWhitespace(ch: string | undefined): boolean {
   755→    return ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n';
   756→  }
   757→
   758→  private isDigit(ch: string | undefined): boolean {
   759→    return ch !== undefined && ch >= '0' && ch <= '9';
   760→  }
   761→
   762→  private isHexDigit(ch: string | undefined): boolean {
   763→    return (
   764→      ch !== undefined &&
   765→      ((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F'))
   766→    );
   767→  }
   768→
   769→  private isOctalDigit(ch: string | undefined): boolean {
   770→    return ch !== undefined && ch >= '0' && ch <= '7';
   771→  }
   772→
   773→  private isIdentifierStart(ch: string | undefined): boolean {
   774→    return (
   775→      ch !== undefined &&
   776→      ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_' || ch === '$')
   777→    );
   778→  }
   779→
   780→  private isIdentifierChar(ch: string | undefined): boolean {
   781→    return this.isIdentifierStart(ch) || this.isDigit(ch);
   782→  }
   783→
   784→  private makeToken(
   785→    type: TokenType,
   786→    value: string,
   787→    mode: 'v' | 'python' | 'auto'
   788→  ): Token {
   789→    return {
   790→      type,
   791→      value,
   792→      line: this.line,
   793→      column: this.column - value.length,
   794→      mode,
   795→      startPos: this.pos - value.length,
   796→      endPos: this.pos,
   797→    };
   798→  }
   799→}
   800→
   801→export default NexusLexer;
   802→

