    39→/** FreeLang 타입 → WASM 타입 */
    40→function toWasmType(flType: string | undefined): string {
    41→  if (!flType) return 'i64'; // 기본값
    42→  switch (flType.trim()) {
    43→    case 'i64': return 'i64';
    44→    case 'f64': return 'f64';
    45→    case 'f32': return 'f32';
    46→    case 'i32': return 'i32';
    47→    case 'bool': return 'i32'; // bool → i32 (WASM에 bool 없음)
    48→    case 'void': return '';    // 반환 없음
    49→    case 'string': return 'i32'; // Phase N.4.3: string → i32 (메모리 포인터)
    50→    default: return 'i64';     // 미지원 타입은 i64 폴백
    51→  }
    52→}
    53→
    54→/** WASM 타입별 산술 연산 opcode */
    55→function wasmBinOp(op: string, wasmType: string): string {
    56→  const t = wasmType === '' ? 'i64' : wasmType;
    57→  switch (op) {
    58→    case '+':  return `${t}.add`;
    59→    case '-':  return `${t}.sub`;
    60→    case '*':  return `${t}.mul`;
    61→    case '/':  return t.startsWith('f') ? `${t}.div` : `${t}.div_s`;
    62→    case '%':  return t.startsWith('f') ? `${t}.rem_f` : `${t}.rem_s`;
    63→    case '==': return t.startsWith('f') ? `${t}.eq` : `${t}.eq`;
    64→    case '!=': return t.startsWith('f') ? `${t}.ne` : `${t}.ne`;
    65→    case '<':  return t.startsWith('f') ? `${t}.lt` : `${t}.lt_s`;
    66→    case '>':  return t.startsWith('f') ? `${t}.gt` : `${t}.gt_s`;
    67→    case '<=': return t.startsWith('f') ? `${t}.le` : `${t}.le_s`;
    68→    case '>=': return t.startsWith('f') ? `${t}.ge` : `${t}.ge_s`;
    69→    case '&&': return 'i32.and';
    70→    case '||': return 'i32.or';
    71→    default:   return `i64.add`; // 폴백
    72→  }
    73→}
    74→
    75→// ─── 코드 생성기 ──────────────────────────────────────────────────────────────
