     1→/**
     2→ * FreeLang Nexus - WebAssembly 런타임 실행기
     3→ *
     4→ * Phase N.4.2 — WAT → .wasm 바이너리 변환 + Node.js 실행
     5→ *
     6→ * 역할:
     7→ *  1. FreeLang 소스 → NexusWasmCodegen으로 WAT 생성
     8→ *  2. wabt npm 패키지로 WAT → .wasm 바이너리 변환
     9→ *  3. WebAssembly.instantiate 로 Node.js에서 실행
    10→ *  4. export된 함수 호출 및 결과 반환
    11→ *
    12→ * wabt 미설치 환경에서는 자동으로 unavailable 플래그를 세움
    13→ */
    14→
    15→import { NexusLexer } from '../lexer/nexus-lexer';
    16→import { NexusParser } from '../parser/nexus-parser';
    17→import { NexusWasmCodegen } from '../codegen/nexus-wasm-codegen';
    18→
    19→// ─── wabt 동적 로드 (미설치 환경 안전 처리) ───────────────────────────────────
    20→
    21→let wabtLoader: (() => Promise<any>) | null = null;
    22→
    23→try {
    24→  // require 시도: wabt 패키지가 있으면 로더 등록
    25→  const wabtModule = require('wabt');
    26→  wabtLoader = wabtModule as () => Promise<any>;
    27→} catch {
    28→  // wabt 미설치 환경: loader = null
    29→  wabtLoader = null;
    30→}
    31→
    32→/** wabt 사용 가능 여부 */
    33→export function isWabtAvailable(): boolean {
    34→  return wabtLoader !== null;
    35→}
    36→
    37→// ─── 결과 타입 ────────────────────────────────────────────────────────────────
    38→
    39→export interface WasmRunResult {
    40→  /** 실행 성공 여부 */
    41→  success: boolean;
    42→  /** export 함수 호출 결과 (성공 시) */
    43→  result?: unknown;
    44→  /** 에러 메시지 (실패 시) */
    45→  error?: string;
    46→  /** 생성된 WAT 텍스트 (디버깅용) */
    47→  wat?: string;
    48→  /** 경고 목록 */
    49→  warnings: string[];
    50→}
    51→
    52→export interface WasmModuleResult {
    53→  /** 실행 성공 여부 */
    54→  success: boolean;
    55→  /** WebAssembly Instance (성공 시) */
    56→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    57→  instance?: any;
    58→  /** export 함수 이름 목록 */
    59→  exports: string[];
    60→  /** 생성된 WAT 텍스트 */
    61→  wat: string;
    62→  /** 경고 목록 */
    63→  warnings: string[];
    64→  /** 에러 메시지 (실패 시) */
    65→  error?: string;
    66→}
    67→
    68→// ─── 메인 클래스 ──────────────────────────────────────────────────────────────
    69→
    70→/**
    71→ * FreeLang 소스 → WAT → WASM → 실행 파이프라인
    72→ *
    73→ * 사용 예:
    74→ *   const runner = new NexusWasmRunner();
    75→ *   const mod = await runner.compileModule(`@mode(v)\nfn add(a:i64,b:i64)->i64{return a+b}`);
    76→ *   const result = runner.callExport(mod, 'add', [3n, 7n]);
    77→ *   // result.result === 10n
    78→ */
    79→export class NexusWasmRunner {
    80→
    81→  // ─── WAT 생성 ───────────────────────────────────────────────────────────────
    82→
    83→  /**
    84→   * FreeLang 소스 → WAT 문자열 생성
    85→   */
    86→  generateWat(source: string): { wat: string; exports: string[]; warnings: string[] } {
    87→    const lexer = new NexusLexer(source);
    88→    const tokens = lexer.tokenize();
    89→    const parser = new NexusParser(tokens);
    90→    const ast = parser.parse();
    91→    const gen = new NexusWasmCodegen();
    92→    return gen.generate(ast);
    93→  }
    94→
    95→  // ─── WAT → WASM 변환 ────────────────────────────────────────────────────────
    96→
    97→  /**
    98→   * WAT 문자열 → Uint8Array(WASM 바이너리)
    99→   * wabt 미설치 시 에러 throw
   100→   */
   101→  async watToWasm(wat: string): Promise<Uint8Array> {
   102→    if (!wabtLoader) {
   103→      throw new Error('wabt 패키지가 설치되지 않았습니다. npm install wabt 를 실행하세요.');
   104→    }
   105→    const wabt = await wabtLoader();
   106→    const module = wabt.parseWat('nexus.wat', wat);
   107→    try {
   108→      const binary = module.toBinary({});
   109→      return binary.buffer;
   110→    } finally {
   111→      module.destroy();
   112→    }
   113→  }
   114→
   115→  // ─── 모듈 컴파일 ────────────────────────────────────────────────────────────
   116→
   117→  /**
   118→   * FreeLang 소스 → WebAssembly.Instance (전체 파이프라인)
   119→   */
   120→  async compileModule(source: string): Promise<WasmModuleResult> {
   121→    // 1. WAT 생성
   122→    let watResult: ReturnType<NexusWasmRunner['generateWat']>;
   123→    try {
   124→      watResult = this.generateWat(source);
   125→    } catch (e: any) {
   126→      return {
   127→        success: false,
   128→        exports: [],
   129→        wat: '',
   130→        warnings: [],
   131→        error: `WAT 생성 실패: ${e?.message ?? e}`,
   132→      };
   133→    }
   134→
   135→    // 2. WASM 변환
   136→    let wasm: Uint8Array;
   137→    try {
   138→      wasm = await this.watToWasm(watResult.wat);
   139→    } catch (e: any) {
   140→      return {
   141→        success: false,
   142→        exports: watResult.exports,
   143→        wat: watResult.wat,
   144→        warnings: watResult.warnings,
   145→        error: `WAT→WASM 변환 실패: ${e?.message ?? e}`,
   146→      };
   147→    }
   148→
   149→    // 3. WebAssembly 인스턴스화 (globalThis.WebAssembly — Node.js 내장)
   150→    // eslint-disable-next-line @typescript-eslint/no-explicit-any

