   153→  private stringTable: Map<string, { offset: number; length: number }> = new Map();
   154→  /** 다음 문자열 배치 오프셋 (누적) */
   155→  private stringOffset: number = 0;
   156→  /** 문자열 기능 사용 여부 (memory/import 추가 여부) */
   157→  private usesStrings: boolean = false;
   158→
   159→  // ─── 공개 인터페이스 ─────────────────────────────────────────────────────────
   160→
   161→  /**
   162→   * Program AST → WAT 생성
   163→   * Python 모드 함수, LangBlock 등은 스킵 (경고만 기록)
   164→   */
   165→  generate(program: AST.Program): WasmCodegenResult {
   166→    this.reset();
   167→
   168→    // Phase N.4.3: 1차 패스 — 문자열 상수 수집 (data 섹션 레이아웃 결정)
   169→    this.scanStrings(program);
   170→
   171→    // module 시작
   172→    this.emit('(module');
   173→    this.indentLevel++;
   174→
   175→    // Phase N.4.3: 문자열 사용 시 memory & host_print import 추가
   176→    if (this.usesStrings) {
   177→      this.emit('(memory (export "memory") 1)');
   178→      // host_print(ptr: i32, len: i32) — 호스트 환경(Node.js/WASI)에서 구현
   179→      this.emit('(import "env" "host_print" (func $host_print (param i32 i32)))');
   180→    }
   181→
   182→    let hasFunctions = false;
   183→    for (const node of program.body) {
   184→      const n = node as any;
   185→      if (n.type === 'VFunction') {
   186→        this.genVFunction(n as AST.VFunction);
   187→        hasFunctions = true;
   188→      } else if (n.type === 'PyFunction') {
   189→        this.warnings.push(`Python 모드 함수 '${(n as AST.PyFunction).name}'은 WASM 미지원 (스킵)`);
   190→      } else if (n.type === 'StructDef') {
   191→        this.warnings.push(`구조체 '${(n as AST.StructDef).name}'은 현재 WASM 미지원 (스킵)`);
   192→      } else if (n.type === 'LangBlock') {
   193→        this.warnings.push(`@lang 블록은 WASM 미지원 (스킵)`);
   194→      } else if (n.type === 'ExternCall') {
   195→        this.warnings.push(`@call 지시문은 WASM 미지원 (스킵)`);
   196→      }
   197→      // 그 외 탑레벨 구문은 무시
   198→    }
   199→
   200→    if (!hasFunctions) {
   201→      this.warnings.push('V 모드 함수가 없습니다. 빈 모듈이 생성됩니다.');
   202→    }
   203→
   204→    // Phase N.4.3: (data ...) 섹션 생성
   205→    if (this.usesStrings) {
   206→      for (const [strVal, { offset }] of this.stringTable) {
   207→        const escaped = stringToWatData(strVal);
   208→        this.emit(`(data (i32.const ${offset}) "${escaped}")`);
   209→      }
   210→    }
   211→
   212→    this.indentLevel--;
   213→    this.emit(')');
   214→
   215→    return {
   216→      wat: this.lines.join('\n'),
   217→      exports: [...this.exports],
   218→      warnings: [...this.warnings],
   219→      stringTable: new Map(this.stringTable),
   220→    };
   221→  }
   222→
   223→  // ─── Phase N.4.3: 문자열 스캔 ────────────────────────────────────────────────
   224→
   225→  /**
   226→   * 프로그램 전체에서 문자열 리터럴을 수집하여 stringTable을 구성합니다.
   227→   * 중복 문자열은 한 번만 저장 (중복 제거).
   228→   */
   229→  private scanStrings(program: AST.Program): void {
   230→    for (const node of program.body) {
   231→      const n = node as any;
   232→      if (n.type === 'VFunction') {
   233→        this.scanStringsInStmts((n as AST.VFunction).body);
   234→      }
   235→    }
   236→  }
   237→
   238→  private scanStringsInStmts(stmts: AST.Statement[]): void {
   239→    for (const stmt of stmts) {
   240→      const s = stmt as any;
   241→      switch (s.type) {
   242→        case 'Return':
   243→          if (s.value) this.scanStringsInExpr(s.value);
   244→          break;
   245→        case 'Assign':
   246→          this.scanStringsInExpr(s.value);
   247→          break;
   248→        case 'ExprStatement':
   249→          this.scanStringsInExpr(s.expression);
   250→          break;
   251→        case 'IfStatement':
   252→          this.scanStringsInExpr(s.condition);
   253→          this.scanStringsInStmts(s.thenBranch || []);
   254→          if (s.elseBranch) this.scanStringsInStmts(s.elseBranch);
   255→          break;
   256→        case 'WhileStatement':
   257→          this.scanStringsInExpr(s.condition);
   258→          this.scanStringsInStmts(s.body || []);
   259→          break;
   260→        case 'ForStatement':
   261→          this.scanStringsInStmts(s.body || []);
   262→          break;
   263→      }
   264→    }
   265→  }
   266→
   267→  private scanStringsInExpr(expr: AST.Expression): void {
   268→    const e = expr as any;
   269→    if (!e) return;
   270→    switch (e.type) {
   271→      case 'String':
   272→        this.registerString(unquoteString(e.value as string));
   273→        break;
   274→      case 'BinaryExpr':
   275→        this.scanStringsInExpr(e.left);
   276→        this.scanStringsInExpr(e.right);
   277→        break;
   278→      case 'Call':
   279→        for (const arg of (e.args || [])) {
   280→          this.scanStringsInExpr(arg);
   281→        }
   282→        break;
   283→    }
   284→  }
