   286→  /**
   287→   * 문자열 상수를 stringTable에 등록 (따옴표가 제거된 실제 내용으로).
   288→   * 이미 등록된 문자열은 중복 추가하지 않음.
   289→   */
   290→  private registerString(s: string): void {
   291→    if (this.stringTable.has(s)) return;
   292→    const length = utf8ByteLength(s);
   293→    this.stringTable.set(s, { offset: this.stringOffset, length });
   294→    this.stringOffset += length;
   295→    this.usesStrings = true;
   296→  }
   297→
   298→  /**
   299→   * 문자열의 메모리 포인터(오프셋)를 i32.const로 스택에 push.
   300→   * s는 따옴표가 제거된 실제 문자열 내용이어야 합니다.
   301→   */
   302→  private emitStringPtr(s: string): void {
   303→    const key = unquoteString(s);
   304→    const entry = this.stringTable.get(key);
   305→    if (entry) {
   306→      this.emit(`i32.const ${entry.offset}  ;; ptr "${key.substring(0, 20)}"`);
   307→    } else {
   308→      this.emit('i32.const 0  ;; unknown string ptr');
   309→    }
   310→  }
   311→
   312→  /**
   313→   * 문자열의 길이를 i32.const로 스택에 push.
   314→   * s는 따옴표가 제거된 실제 문자열 내용이어야 합니다.
   315→   */
   316→  private emitStringLen(s: string): void {
   317→    const key = unquoteString(s);
   318→    const entry = this.stringTable.get(key);
   319→    if (entry) {
   320→      this.emit(`i32.const ${entry.length}  ;; len "${key.substring(0, 20)}"`);
   321→    } else {
   322→      this.emit('i32.const 0  ;; unknown string len');
   323→    }
   324→  }
   325→
   326→  // ─── 내부 헬퍼 ──────────────────────────────────────────────────────────────
   327→
   328→  private reset(): void {
   329→    this.lines = [];
   330→    this.indentLevel = 0;
   331→    this.exports = [];
   332→    this.warnings = [];
   333→    this.localTypes = new Map();
   334→    this.paramNames = new Set();
   335→    this.loopLabelStack = [];
   336→    this.loopCounter = 0;
   337→    this.stringTable = new Map();
   338→    this.stringOffset = 0;
   339→    this.usesStrings = false;
   340→  }
   341→
   342→  private emit(line: string): void {
   343→    const indent = '  '.repeat(this.indentLevel);
   344→    this.lines.push(indent + line);
   345→  }
   346→
   347→  private indent(): void  { this.indentLevel++; }
   348→  private dedent(): void  { this.indentLevel = Math.max(0, this.indentLevel - 1); }
